// Mark only the historical terms; the original mnemonic wording stays intact.
export const HISTORICAL_TERMS={
 w375:['ゲルマン民族','大移動'],w476:['西ローマ'],w589:['隋','中国統一'],w610:['イスラム教'],w676:['新羅'],w800:['カール','皇帝'],w936:['高麗'],w1096:['十字軍'],w1215:['ジョン','マグナ・カルタ'],w1453:['東ローマ'],w1492:['コロンブス','西インド'],w1498:['ガマ','インド'],w1512:['ミケランジェロ','天井画'],w1517:['ルター','宗教改革'],w1522:['船隊','世界一周'],w1543:['コペルニクス','地動説'],w1600:['イギリス東インド会社'],w1642:['ピューリタン革命'],w1688:['名誉革命'],w1748:['モンテスキュー','法の精神'],w1762:['ルソー','社会契約論'],w1776:['アメリカ独立'],w1789:['フランス革命'],w1804:['ナポレオン','皇帝'],w1815:['ウィーン会議'],w1840:['アヘン戦争'],w1851:['太平天国の乱'],w1853:['クリミア'],w1857:['インド大反乱'],w1861:['南北戦争'],
 j478:['武','宋'],j593:['太子','摂政'],j607:['小野妹子','隋'],j645:['大化の改新'],j663:['白村江'],j672:['壬申の乱'],j701:['大宝律令'],j710:['平城京'],j743:['墾田永年私財法'],j794:['平安京'],j894:['遣唐使'],j939:['将門','新皇'],j1016:['道長','摂政'],j1086:['白河','院政'],j1167:['清盛','太政大臣'],j1185:['守護','地頭'],j1221:['承久の乱'],j1232:['泰時','御成敗式目'],j1334:['後醍醐','建武の新政'],j1404:['勘合','日明貿易'],j1428:['正長の土一揆'],j1467:['応仁の乱'],j1485:['山城国一揆'],j1488:['加賀の一向一揆'],j1543:['鉄砲'],j1549:['ザビエル','キリスト教'],j1573:['室町幕府'],j1582:['本能寺の変'],j1588:['秀吉','刀狩令'],j1592:['文禄の役'],j1600:['関ヶ原'],j1603:['家康','江戸幕府'],j1615:['武家諸法度'],j1635:['参勤交代','大名行列'],j1637:['島原・天草一揆'],j1639:['ポルトガル船','鎖国'],j1709:['新井白石'],j1716:['吉宗','享保'],j1742:['公事方御定書'],j1772:['田沼','老中'],j1774:['解体新書'],j1787:['寛政の改革'],j1792:['ラクスマン'],j1825:['異国船'],j1837:['大塩の乱'],j1841:['水野忠邦','天保の改革'],j1853:['ペリー','黒船'],j1858:['修好通商条約'],j1860:['桜田門外の変'],j1867:['大政奉還']
};
const escapeHTML=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function highlightMnemonic(id,text){
 const terms=[...(HISTORICAL_TERMS[id]||[])].sort((a,b)=>b.length-a.length);
 let result='';
 for(let i=0;i<text.length;){
  const term=terms.find(term=>text.startsWith(term,i));
  if(term){result+='<strong class="historical-term">'+escapeHTML(term)+'</strong>';i+=term.length;}
  else result+=escapeHTML(text[i++]);
 }
 return result;
}
